CREATE TABLE public.site_owners (user_id uuid PRIMARY KEY);
GRANT SELECT ON public.site_owners TO authenticated;
GRANT ALL ON public.site_owners TO service_role;
ALTER TABLE public.site_owners ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own ownership" ON public.site_owners FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_site_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.site_owners WHERE user_id = auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_site_owner() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_site_owner() TO authenticated, service_role;
CREATE TABLE public.schools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(char_length(btrim(name)) BETWEEN 2 AND 160), created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX schools_name_unique ON public.schools (lower(btrim(name)));
GRANT SELECT ON public.schools TO authenticated;
GRANT ALL ON public.schools TO service_role;
ALTER TABLE public.schools ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Signed in school directory" ON public.schools FOR SELECT TO authenticated USING (true);
CREATE TABLE public.school_memberships (user_id uuid PRIMARY KEY, school_id uuid NOT NULL REFERENCES public.schools(id), member_role text NOT NULL CHECK(member_role IN ('student','staff')), staff_title text NOT NULL DEFAULT '' CHECK(staff_title IN ('','DOS','HT','Discipline Master')), status text NOT NULL CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), CHECK((member_role='student' AND staff_title='') OR (member_role='staff' AND staff_title<>'')));
GRANT SELECT ON public.school_memberships TO authenticated;
GRANT ALL ON public.school_memberships TO service_role;
ALTER TABLE public.school_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own membership or owner approvals" ON public.school_memberships FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_site_owner());
CREATE FUNCTION public.is_school_staff(_school_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.school_memberships WHERE user_id=auth.uid() AND school_id=_school_id AND member_role='staff' AND status='approved') $$;
REVOKE ALL ON FUNCTION public.is_school_staff(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_school_staff(uuid) TO authenticated, service_role;
CREATE FUNCTION public.request_school_membership(_school_id uuid, _role text, _title text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
 IF _role NOT IN ('student','staff') OR (_role='student' AND _title<>'') OR (_role='staff' AND _title NOT IN ('DOS','HT','Discipline Master')) THEN RAISE EXCEPTION 'Invalid school role'; END IF;
 IF EXISTS(SELECT 1 FROM public.school_memberships WHERE user_id=auth.uid() AND status='approved') THEN RAISE EXCEPTION 'An approved membership cannot be changed here'; END IF;
 INSERT INTO public.school_memberships(user_id,school_id,member_role,staff_title,status) VALUES(auth.uid(),_school_id,_role,_title,CASE WHEN _role='student' THEN 'approved' ELSE 'pending' END) ON CONFLICT(user_id) DO UPDATE SET school_id=EXCLUDED.school_id,member_role=EXCLUDED.member_role,staff_title=EXCLUDED.staff_title,status=EXCLUDED.status;
 END $$;
REVOKE ALL ON FUNCTION public.request_school_membership(uuid,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.request_school_membership(uuid,text,text) TO authenticated;
CREATE FUNCTION public.create_school(_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.is_site_owner() THEN RAISE EXCEPTION 'Owner access required'; END IF; INSERT INTO public.schools(name) VALUES(btrim(_name)) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.create_school(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_school(text) TO authenticated;
CREATE FUNCTION public.review_school_membership(_user_id uuid, _approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_site_owner() THEN RAISE EXCEPTION 'Owner access required'; END IF; UPDATE public.school_memberships SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END WHERE user_id=_user_id AND member_role='staff'; IF NOT FOUND THEN RAISE EXCEPTION 'Staff request not found'; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_school_membership(uuid,boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.review_school_membership(uuid,boolean) TO authenticated;
ALTER TABLE public.reports ADD COLUMN school_id uuid REFERENCES public.schools(id);
CREATE INDEX reports_school_created_idx ON public.reports(school_id,created_at DESC);
CREATE FUNCTION public.assign_report_school() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE membership public.school_memberships%ROWTYPE; BEGIN
 SELECT * INTO membership FROM public.school_memberships WHERE user_id=NEW.owner_id;
 IF FOUND THEN IF membership.member_role<>'student' OR membership.status<>'approved' THEN RAISE EXCEPTION 'Only approved students can submit school reports'; END IF; NEW.school_id:=membership.school_id;
 ELSE IF NEW.school_id IS NOT NULL THEN RAISE EXCEPTION 'School membership required'; END IF; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER assign_report_school BEFORE INSERT ON public.reports FOR EACH ROW EXECUTE FUNCTION public.assign_report_school();
ALTER POLICY "Staff read all reports" ON public.reports USING (school_id IS NULL AND public.has_role(auth.uid(),'staff'));
CREATE POLICY "School staff read school reports" ON public.reports FOR SELECT TO authenticated USING(public.is_school_staff(school_id));
ALTER POLICY "Staff read report photos" ON storage.objects USING (bucket_id='report-photos' AND EXISTS(SELECT 1 FROM public.reports r WHERE r.photo_path=name AND ((r.school_id IS NULL AND public.has_role(auth.uid(),'staff')) OR public.is_school_staff(r.school_id))));
CREATE TABLE public.report_feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES public.reports(id) ON DELETE CASCADE, sender_id uuid NOT NULL DEFAULT auth.uid(), staff_title text NOT NULL DEFAULT '', message text NOT NULL CHECK(char_length(btrim(message)) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.report_feedback TO authenticated;
GRANT ALL ON public.report_feedback TO service_role;
ALTER TABLE public.report_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants read private feedback" ON public.report_feedback FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.reports r WHERE r.id=report_id AND (r.owner_id=auth.uid() OR public.is_school_staff(r.school_id))));
CREATE POLICY "School staff send feedback" ON public.report_feedback FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.reports r WHERE r.id=report_id AND public.is_school_staff(r.school_id)));
CREATE TABLE public.school_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_id uuid NOT NULL, report_id uuid NOT NULL REFERENCES public.reports(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('student_report','staff_feedback')), created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
GRANT SELECT ON public.school_notifications TO authenticated;
GRANT UPDATE(read_at) ON public.school_notifications TO authenticated;
GRANT ALL ON public.school_notifications TO service_role;
ALTER TABLE public.school_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Recipients read their alerts" ON public.school_notifications FOR SELECT TO authenticated USING(recipient_id=auth.uid() AND EXISTS(SELECT 1 FROM public.reports r WHERE r.id=report_id AND (r.owner_id=auth.uid() OR public.is_school_staff(r.school_id))));
CREATE POLICY "Recipients mark alerts read" ON public.school_notifications FOR UPDATE TO authenticated USING(recipient_id=auth.uid()) WITH CHECK(recipient_id=auth.uid());
CREATE INDEX school_notifications_recipient_idx ON public.school_notifications(recipient_id,created_at DESC);
CREATE FUNCTION public.notify_school_staff() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.school_id IS NOT NULL THEN INSERT INTO public.school_notifications(recipient_id,report_id,kind) SELECT user_id,NEW.id,'student_report' FROM public.school_memberships WHERE school_id=NEW.school_id AND member_role='staff' AND status='approved'; END IF; RETURN NEW; END $$;
CREATE TRIGGER notify_school_staff AFTER INSERT ON public.reports FOR EACH ROW EXECUTE FUNCTION public.notify_school_staff();
CREATE FUNCTION public.prepare_school_feedback() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE school uuid; BEGIN SELECT school_id INTO school FROM public.reports WHERE id=NEW.report_id; IF NEW.sender_id<>auth.uid() OR NOT public.is_school_staff(school) THEN RAISE EXCEPTION 'Approved school staff required'; END IF; SELECT staff_title INTO NEW.staff_title FROM public.school_memberships WHERE user_id=auth.uid(); NEW.created_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER prepare_school_feedback BEFORE INSERT ON public.report_feedback FOR EACH ROW EXECUTE FUNCTION public.prepare_school_feedback();
CREATE FUNCTION public.notify_student_feedback() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.school_notifications(recipient_id,report_id,kind) SELECT owner_id,NEW.report_id,'staff_feedback' FROM public.reports WHERE id=NEW.report_id; RETURN NEW; END $$;
CREATE TRIGGER notify_student_feedback AFTER INSERT ON public.report_feedback FOR EACH ROW EXECUTE FUNCTION public.notify_student_feedback();
ALTER PUBLICATION supabase_realtime ADD TABLE public.school_notifications;
ALTER PUBLICATION supabase_realtime ADD TABLE public.report_feedback;
ALTER PUBLICATION supabase_realtime ADD TABLE public.school_memberships;
CREATE OR REPLACE FUNCTION public.list_shared_reports(page_number integer DEFAULT 0) RETURNS TABLE(id uuid,description text,location text,category text,summary text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.id,r.description,r.location,r.category,r.summary,r.created_at FROM public.reports r WHERE r.school_id IS NULL ORDER BY r.created_at DESC,r.id LIMIT 30 OFFSET(greatest(0,least(page_number,10000))*30) $$;
CREATE OR REPLACE FUNCTION public.list_reports_since_signup(page_number integer DEFAULT 0) RETURNS TABLE(id uuid,description text,location text,category text,summary text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.id,r.description,r.location,r.category,r.summary,r.created_at FROM public.reports r WHERE auth.uid() IS NOT NULL AND r.created_at >= (SELECT u.created_at FROM auth.users u WHERE u.id=auth.uid()) AND (r.school_id IS NULL OR EXISTS(SELECT 1 FROM public.school_memberships m WHERE m.user_id=auth.uid() AND m.school_id=r.school_id AND m.status='approved')) ORDER BY r.created_at DESC,r.id LIMIT 30 OFFSET(greatest(0,least(page_number,10000))*30) $$;